#!/usr/bin/env python3
"""Male Body V5 — self-contained GLB builder and Master Skeleton pipeline.

RUN: python male_body_standalone.py
DEPS: python -m pip install numpy scipy
OPTIONAL: python -m pip install vtk pillow  (for --preview)

No external source GLB, JSON, or project Python file is required.
Source mesh: user-provided male-base-mesh-base_male.glb, Innerscene Corp,
CC0 1.0 per its glTF asset copyright field. Original bytes embedded losslessly.
Garment reference: only the necessary original skeleton metadata and inverse
bind matrices are embedded; garment vertices are not used by this pipeline.

EDITING WITH AI: all editable geometry, material, skinning and export logic
is above the EMBEDDED DATA marker. Run --print-code to extract that part
without the large source payload. Do not edit the encoded mesh by hand.
The default builds anatomy + V5; --version all also builds V4.
Generated anatomy GLBs are intermediate outputs, not external inputs.
"""
import argparse, base64, copy, hashlib, json, lzma, struct
from pathlib import Path
import numpy as np

def _quat_to_mat(q):
    x, y, z, w = q
    n = (x*x + y*y + z*z + w*w) ** 0.5
    if n > 1e-12:
        x, y, z, w = x/n, y/n, z/n, w/n
    return np.array([
        [1-2*(y*y+z*z), 2*(x*y-z*w), 2*(x*z+y*w)],
        [2*(x*y+z*w), 1-2*(x*x+z*z), 2*(y*z-x*w)],
        [2*(x*z-y*w), 2*(y*z+x*w), 1-2*(x*x+y*y)],
    ], dtype=float)

def _mat_to_quat(R):
    tr = R[0,0] + R[1,1] + R[2,2]
    if tr > 0:
        s = 2.0 * (tr + 1.0) ** 0.5
        w = 0.25 * s
        x = (R[2,1] - R[1,2]) / s
        y = (R[0,2] - R[2,0]) / s
        z = (R[1,0] - R[0,1]) / s
    elif R[0,0] > R[1,1] and R[0,0] > R[2,2]:
        s = 2.0 * (1.0 + R[0,0] - R[1,1] - R[2,2]) ** 0.5
        w = (R[2,1] - R[1,2]) / s
        x = 0.25 * s
        y = (R[0,1] + R[1,0]) / s
        z = (R[0,2] + R[2,0]) / s
    elif R[1,1] > R[2,2]:
        s = 2.0 * (1.0 + R[1,1] - R[0,0] - R[2,2]) ** 0.5
        w = (R[0,2] - R[2,0]) / s
        x = (R[0,1] + R[1,0]) / s
        y = 0.25 * s
        z = (R[1,2] + R[2,1]) / s
    else:
        s = 2.0 * (1.0 + R[2,2] - R[0,0] - R[1,1]) ** 0.5
        w = (R[1,0] - R[0,1]) / s
        x = (R[0,2] + R[2,0]) / s
        y = (R[1,2] + R[2,1]) / s
        z = 0.25 * s
    q = np.array([x, y, z, w], dtype=float)
    q /= max(np.linalg.norm(q), 1e-12)
    return q

def _quat_mul(a, b):
    ax, ay, az, aw = a; bx, by, bz, bw = b
    return np.array([
        aw*bx + ax*bw + ay*bz - az*by,
        aw*by - ax*bz + ay*bw + az*bx,
        aw*bz + ax*by - ay*bx + az*bw,
        aw*bw - ax*bx - ay*by - az*bz,
    ], dtype=float)

CT={5120:'i1',5121:'u1',5122:'<i2',5123:'<u2',5125:'<u4',5126:'<f4'}
DIM={'SCALAR':1,'VEC2':2,'VEC3':3,'VEC4':4,'MAT4':16}
class GLB:
    def __init__(self,path):
        b = bytes(path) if isinstance(path, (bytes, bytearray, memoryview)) else Path(path).read_bytes()
        magic,ver,size=struct.unpack_from('<4sII',b)
        if magic!=b'glTF' or ver!=2 or size!=len(b): raise ValueError('Not a valid GLB 2.0')
        self.d={}; self.b=b''; p=12
        while p<len(b):
            n,t=struct.unpack_from('<I4s',b,p); p+=8
            if t==b'JSON': self.d=json.loads(b[p:p+n])
            elif t==b'BIN\0': self.b=b[p:p+n]
            p+=n
        self.parents={c:i for i,n in enumerate(self.d['nodes']) for c in n.get('children',[])}
        self.world={}
    def matrix(self,i):
        if i in self.world:return self.world[i]
        n=self.d['nodes'][i]
        if 'matrix' in n:m=np.array(n['matrix']).reshape(4,4).T
        else:
            m=np.eye(4);m[:3,:3]=_quat_to_mat(n.get('rotation',[0,0,0,1]))@np.diag(n.get('scale',[1,1,1]));m[:3,3]=n.get('translation',[0,0,0])
        if i in self.parents:m=self.matrix(self.parents[i])@m
        self.world[i]=m;return m
    def read(self,i,normalize=False):
        a=self.d['accessors'][i]; v=self.d['bufferViews'][a['bufferView']]; dt=np.dtype(CT[a['componentType']]); k=DIM[a['type']]
        if a.get('sparse') or v.get('buffer',0)!=0:raise ValueError('Unsupported sparse/external accessor')
        x=np.ndarray((a['count'],k),dtype=dt,buffer=self.b,offset=v.get('byteOffset',0)+a.get('byteOffset',0),strides=(v.get('byteStride',k*dt.itemsize),dt.itemsize)).copy()
        if normalize and a.get('normalized') and dt.kind in 'iu': x=np.maximum(-1,x.astype(float)/np.iinfo(dt).max)
        return x

def build_anatomy(source, reference, ROOT):
    src=GLB(source); ref=GLB(reference)
    ss=src.d['skins'][0]; rs=ref.d['skins'][0]; ib=ref.read(rs['inverseBindMatrices']); rm=np.linalg.inv(ib.reshape(-1,4,4).transpose(0,2,1));
    rn={ref.d['nodes'][i]['name'].split(':')[-1]:j for j,i in enumerate(rs['joints'])}; sn={n['name']:i for i,n in enumerate(src.d['nodes'])}; S=lambda k:src.matrix(sn[k])[:3,3]
    # Exact source-to-destination joint assignment, including twist, facial and digit chains.
    mp={'root':'Hips','pelvis.L':'Hips','pelvis.R':'Hips','spine05':'Hips','spine04':'Spine','spine03':'Spine1','spine02':'Spine1','spine01':'Spine2','breast.L':'Spine2','breast.R':'Spine2','neck01':'Neck','neck02':'Neck','neck03':'Neck','head':'Head'}
    for s,side in [('L','Left'),('R','Right')]:
     for a,b in [('clavicle','Shoulder'),('shoulder01','Shoulder'),('upperarm01','Arm'),('upperarm02','Arm'),('lowerarm01','ForeArm'),('lowerarm02','ForeArm'),('wrist','Hand'),('upperleg01','UpLeg'),('upperleg02','UpLeg'),('lowerleg01','Leg'),('lowerleg02','Leg'),('foot','Foot')]:mp[a+'.'+s]=side+b
    reverse={sn[k]:v for k,v in mp.items()}
    def mapnode(i):
     while i not in reverse: i=src.parents[i]
     return reverse[i]
    jsrc=np.array([rn[mapnode(i)] for i in ss['joints']]);
    # Preserve source anatomy; only apply a uniform scale and offset.
    # Joint positions are derived from the source rig, not the old garment.
    parts=[]
    for m in src.d['meshes']:
     for p in m['primitives']:
      at=p['attributes'];v=src.read(at['POSITION']).astype(float);uv=src.read(at['TEXCOORD_0']);n=src.read(at['NORMAL']);f=src.read(p['indices']).reshape(-1,3).astype(int);j=src.read(at['JOINTS_0']);w=src.read(at['WEIGHTS_0'],True);weights=np.zeros((len(v),40))
      for c in range(4):np.add.at(weights,(np.arange(len(v)),jsrc[j[:,c]]),w[:,c]);
      weights/=weights.sum(1,keepdims=True)
      # Blend neck/head weights below the jaw; do not distort facial geometry.
      q=np.clip((v[:,1]-1.49)/(1.575-1.49),0,1);q=q*q*(3-2*q)
      weights*=1-q[:,None];weights[:,rn['Head']]+=q
