def build_athletic(D):

    def smooth(a,b,x):
     t=np.clip((x-a)/(b-a),0,1);return t*t*(3-2*t)
    def ga(x,c,s):return np.exp(-.5*((x-c)/s)**2)
    def sculpt(v):
     x,y,z=v.T; a=np.abs(x); out=v.copy().astype(float)
     # Chest/back breadth, tapered toward the waist and neckline. Also gently thicken shoulders.
     torso=1-smooth(.16,.27,a)
     front=smooth(.022,.075,z); back=1-smooth(-.07,-.015,z)
     broad=ga(y,1.265,.085)*ga(a,.14,.10)
     out[:,0]+=np.sign(x)*(.013*broad + .004*ga(y,1.17,.09)*ga(a,.12,.065))*smooth(.018,.065,a)
     # Build unified pectoral form, with soft transition to clavicles and armpits.
     pec=(ga(x,.084,.047)+ga(x,-.084,.047))*ga(y,1.238,.037)*(1-smooth(.15,.20,a))
     lowerline=ga(y,1.187+.13*(a-.075),.010)*ga(a,.085,.048)*smooth(.02,.04,a)
     out[:,2]+=front*(.030*pec-.0025*lowerline)
     # Latissimus and upper back (no abrupt shape boundaries).
     out[:,2]-=back*torso*(.012*ga(y,1.25,.085)*ga(a,.10,.07)+.005*ga(y,1.13,.075)*ga(a,.09,.05))
     # Abdominal wall: three staggered pairs, broad and connected rather than isolated balls.
     absprofile=sum(h*ga(y,c,.0155) for c,h in [(1.158,.0145),(1.115,.014),(1.073,.0115)])
     abx=(ga(x,.035,.022)+ga(x,-.035,.022))*(1-smooth(.075,.11,a))
     oblique=.007*ga(a,.099,.027)*ga(y,1.10,.060)
     belly=.004*ga(y,1.07,.079)*ga(a,.045,.057)
     out[:,2]+=front*(abx*absprofile+oblique+belly-.0015*ga(x,0,.012)*ga(y,1.115,.055))
     # Actual surface detail: areolar mound + small nipple, and inward umbilicus.
     nr=((a-.085)/.0085)**2+((y-1.205)/.0075)**2
     nipple= .0018*np.exp(-.5*nr)+.0032*np.exp(-.5*(((a-.085)/.0027)**2+((y-1.205)/.0026)**2))
     nav=((x)/.0075)**2+((y-1.041)/.0055)**2
     out[:,2]+=front*(nipple-.0045*np.exp(-.5*nav)+.0015*ga(x,0,.011)*ga(y,1.049,.0045))
     # Limb hypertrophy relative to the existing bone segment. No changes to joint pivots or hands.
     for s in [-1,1]:
      for A,B,amount,c,w in [([s*.187,1.315,-.008],[s*.344,1.133,-.009],.22,.30,.25),([s*.344,1.133,-.009],[s*.471,1.012,.172],.13,.35,.25),([s*.102,.883,-.032],[s*.14,.48,0],.115,.32,.28),([s*.14,.48,0],[s*.186,.068,-.012],.14,.34,.20)]:
       A=np.array(A); B=np.array(B); ab=B-A; t=(v-A)@ab/(ab@ab); radial=v-A-t[:,None]*ab
       gate=smooth(-.10,.10,t)*(1-smooth(.78,1.02,t))*ga(t,c,w)
       if A[1]>1:
        gate*=smooth(.155,.235,a)*(x*s>0)*(1-smooth(.075,.14,np.linalg.norm(radial,axis=1)))
       else:
        gate*=smooth(.018,.065,x*s)*(1-smooth(.09,.15,np.linalg.norm(radial,axis=1)))
       out+=radial*(amount*gate)[:,None]
     return out

    def colors(v):
     x,y,z=v.T;a=abs(x);front=smooth(.025,.075,z)
     r=((a-.085)/.009)**2+((y-1.205)/.008)**2
     areola=np.exp(-.5*r)**1.3*front
     tip=ga(a,.085,.003)*ga(y,1.205,.003)*front
     navel=ga(x,0,.006)*ga(y,1.041,.004)*front
     col=np.ones((len(v),3));col-=areola[:,None]*np.array([.13,.30,.33]);col-=tip[:,None]*np.array([.065,.10,.10]);col-=navel[:,None]*np.array([.23,.27,.30]);return np.clip(col,0,1)

    def export(src,dst):
     g=GLB(src); d=copy.deepcopy(g.d); data=bytearray(g.b)
     def add(a,typ,ct=5126,target=34962,bounds=False):
      a=np.ascontiguousarray(a,dtype={5126:'<f4',5121:'u1'}[ct]);data.extend(b'\0'*((-len(data))%4));off=len(data);data.extend(a.tobytes());d['bufferViews'].append({'buffer':0,'byteOffset':off,'byteLength':a.nbytes,'target':target}); ac={'bufferView':len(d['bufferViews'])-1,'componentType':ct,'count':len(a),'type':typ};
      if bounds:ac.update(min=a.min(0).tolist(),max=a.max(0).tolist())
      if ct==5121:ac['normalized']=True
      d['accessors'].append(ac);return len(d['accessors'])-1
     for p in d['meshes'][0]['primitives']:
      at=p['attributes'];v=g.read(at['POSITION']).astype(float);n=g.read(at['NORMAL']).astype(float);f=g.read(p['indices']).reshape(-1,3);new=sculpt(v)
      # Transform authored normals by inverse transpose of local deformation gradient, preserving seams.
      eps=.00015; J=np.stack([(sculpt(v+np.eye(3)[i]*eps)-sculpt(v-np.eye(3)[i]*eps))/(2*eps) for i in range(3)],axis=2)
      nn=np.linalg.solve(J.transpose(0,2,1),n[:,:,None])[:,:,0]; nn/=np.maximum(np.linalg.norm(nn,axis=1,keepdims=True),1e-12)
      at['POSITION']=add(new,'VEC3',bounds=True);at['NORMAL']=add(nn,'VEC3')
      if p['material']==0:at['COLOR_0']=add(np.round(colors(v)*255),'VEC3',5121)
      assert np.isfinite(new).all() and np.isfinite(nn).all() and (np.linalg.det(J)>0).all()
     d['meshes'][0]['name']='MaleBody_Athletic_Master40';
     for n in d['nodes']:
      if 'mesh' in n:n['name']='MaleBody_Athletic_Master40'
     d['asset']['generator']='Male Anatomy athletic surface sculpt';d['asset']['extras']['rigVersion']='Master40 anatomy bind pose';d['buffers'][0]['byteLength']=len(data)
