    def export(src,dst):
     g=GLB(src); d=copy.deepcopy(g.d); data=bytearray(g.b)
     def add(a,typ,ct=5126,target=34962,bounds=False):
      a=np.ascontiguousarray(a,dtype={5126:'<f4',5121:'u1'}[ct]);data.extend(b'\0'*((-len(data))%4));off=len(data);data.extend(a.tobytes());d['bufferViews'].append({'buffer':0,'byteOffset':off,'byteLength':a.nbytes,'target':target}); ac={'bufferView':len(d['bufferViews'])-1,'componentType':ct,'count':len(a),'type':typ};
      if bounds:ac.update(min=a.min(0).tolist(),max=a.max(0).tolist())
      if ct==5121:ac['normalized']=True
      d['accessors'].append(ac);return len(d['accessors'])-1
