     d['materials'][0]['pbrMetallicRoughness'].update(baseColorFactor=[.57,.395,.30,1],roughnessFactor=.82);d['materials'][2]['pbrMetallicRoughness']['baseColorFactor']=[.50,.30,.25,1];d['materials'][3]['pbrMetallicRoughness']['baseColorFactor']=[.51,.49,.45,1];d['meshes'][0]['name']='MaleBody_Refined_Master40';
     for n in d['nodes']:
      if 'mesh' in n:n['name']='MaleBody_Refined_Master40'
     d['asset']['generator']='Male Anatomy refined surface sculpt';d['asset']['extras']['rigVersion']='Master40 anatomy bind pose';d['buffers'][0]['byteLength']=len(data)
     js=json.dumps(d,separators=(',',':')).encode();js+=b' '*((-len(js))%4);data.extend(b'\0'*((-len(data))%4));Path(dst).write_bytes(struct.pack('<4sII',b'glTF',2,28+len(js)+len(data))+struct.pack('<I4s',len(js),b'JSON')+js+struct.pack('<I4s',len(data),b'BIN\0')+data)
     out=GLB(dst); assert g.d['skins']==out.d['skins']; assert np.array_equal(g.read(g.d['skins'][0]['inverseBindMatrices']),out.read(out.d['skins'][0]['inverseBindMatrices']))
     for j in g.d['skins'][0]['joints']:assert g.d['nodes'][j]==out.d['nodes'][j]
     print(dst, len(data),sum(out.d['accessors'][p['indices']]['count']//3 for p in out.d['meshes'][0]['primitives']))
